def _demo_profile(year, month, meter_id):
    # Deterministic realistic-looking daily values for presentation only.
    seed = (int(meter_id[-2:]) if meter_id[-2:].isdigit() else 7) / 10.0
    days = min(calendar.monthrange(year, month)[1], 18)
    result = []
    for day in range(1, days + 1):
        usage = round(2.4 + ((day * 7) % 11) * 0.37 + seed, 2)
        result.append({"ots": f"{year}-{month:02d}-{day:02d}T00:00:00", "osum": usage})
    return result

def _demo_meter_result(meter):
    data = dict(meter)
    raw = data.get("con_name") or data.get("con_account") or "N/A"
    data["con_account_display"] = clean_account_display(raw)
    return data

def _demo_find_by_apartment(query):
    q = query.strip().upper().replace("-", "")
    for meter in DEMO_METERS.values():
        apt = str(meter.get("con_account", "")).upper().replace("-", "")
        if apt == q:
            return _demo_meter_result(meter)
    raise Exception("Apartment label not found.")

def _demo_find_by_meter_id(query):
    meter = DEMO_METERS.get(str(query).strip())
    if not meter:
        raise Exception("Meter ID not found.")
    return _demo_meter_result(meter)



def get_remote_headers(
    session_id="", meter_id="0", tz_id="0", date_from="", date_to=""
):
    headers = {}
    if session_id:
        headers["x-session-id"] = session_id
    if meter_id and meter_id != "0":
        headers["x-meter-id"] = str(meter_id)
    if tz_id:
        headers["x-tz-id"] = str(tz_id)
    if date_from:
        headers["x-date-from"] = date_from
    if date_to:
        headers["x-date-to"] = date_to
    return headers


def fetch_single_meter_status(target_meter_id):
    """Fetched using master credentials and direct meter status lookup"""
    encoded_password = base64.b64encode(MASTER_PASS.encode("utf-8")).decode(
        "ascii"
    )
    login_response = requests.post(
        f"{BASE_URL}/api/login",
        data={"username": MASTER_USER, "password": encoded_password},
        headers={
            "User-Agent": "Dart/2.19 (dart:io)",
            "Content-Type": "application/x-www-form-urlencoded; charset=utf-8",
        },
        timeout=15,
    )
    login_response.raise_for_status()
    login = login_response.json()

    if not login.get("result") or not login.get("session_id"):
        raise Exception("Gateway communication error.")

    session_id = login.get("session_id")
    status_res = requests.get(
        f"{BASE_URL}/api/status",
        headers={
            "X-SESSION-ID": session_id,
            "X-METER-ID": str(target_meter_id),
            "X-TZ-ID": "0",
        },
        timeout=15,
    )
    status_res.raise_for_status()
    status = status_res.json()

    credit = status.get("tr_balance_last", 0.0)
    raw_account = (
        status.get("con_name")
        or status.get("con_account")
        or status.get("flatnumber")
        or "Unknown"
    )

    return {
        "m_id": target_meter_id,
        "meter_id": target_meter_id,
        "con_account": raw_account,
        "con_account_display": clean_account_display(raw_account),
        "serialnumber": status.get("serialnumber", "Unavailable"),
        "tr_balance_last": credit,
    }




def clean_account_display(raw_account):
    """Hide only a trailing Unknown description while preserving real resident/service-office text."""
    if not raw_account:
        return "N/A"

    text = str(raw_account).strip()

    # Common API form: "A-04-18 /Unknown" or "A-04-18 / John Doe".
    if "/" in text:
        apartment, description = text.split("/", 1)
        apartment = apartment.strip()
        description = description.strip()
        if description.lower() == "unknown":
            return apartment or "N/A"
        return f"{apartment} / {description}" if description else apartment

    # Also handle values such as "A-04-18 Unknown" without affecting real names.
    parts = text.rsplit(None, 1)
    if len(parts) == 2 and parts[1].strip().lower() == "unknown":
        return parts[0].strip() or "N/A"

    return text

def split_account_description(raw_account):
    """Helper function to separate apartment labels from extra text (e.g. 'A-04-10 Name')"""
    if not raw_account:
        return "", ""
    parts = str(raw_account).split(maxsplit=1)
    if len(parts) > 1:
        return parts[0], parts[1]
    return raw_account, ""


def fetch_meter_by_apartment(target_apt):
    """Looks up an apartment using master credentials via /api/meters with flexible matching"""
    encoded_password = base64.b64encode(MASTER_PASS.encode("utf-8")).decode("ascii")
    login_response = requests.post(
        f"{BASE_URL}/api/login",
        data={"username": MASTER_USER, "password": encoded_password},
        headers={"User-Agent": "Dart/2.19 (dart:io)", "Content-Type": "application/x-www-form-urlencoded; charset=utf-8"},
        timeout=15
    )
    login_response.raise_for_status()
    login = login_response.json()

    if not login.get("result"):
        raise Exception("Gateway communication error.")

    session_id = login.get("session_id")
    if not session_id:
        raise Exception("Gateway communication error.")

    meters_res = requests.get(
        f"{BASE_URL}/api/meters", 
        headers={"X-SESSION-ID": session_id, "X-METER-ID": "0", "X-TZ-ID": "2"},
        timeout=15
    )
    meters_res.raise_for_status()
    meters = meters_res.json()
    
    meter_list = meters.get("meters", [])
    if not meter_list:
        raise Exception("No meters found in the system.")

    target_normalized = target_apt.strip().upper()
    matched_meter_id = None

    for meter in meter_list:
        raw_account = meter.get("con_name") or meter.get("con_account") or meter.get("flatnumber") or ""
        apartment, _ = split_account_description(raw_account)
        
        norm_current = apartment.strip().upper()
        if norm_current == target_normalized or norm_current.replace("-", "") == target_normalized.replace("-", ""):
            matched_meter_id = meter.get("meter_id") or meter.get("m_id")
            break

    if not matched_meter_id:
        raise Exception("Apartment label not found in system.")

    return fetch_single_meter_status(matched_meter_id)


def fetch_quick_by_apartment(apartment_label):
    """Quick Check apartment lookup using the same login method as the old working code."""
    apt_code = apartment_label.strip().upper()
    encoded_password = base64.b64encode(apt_code.encode("utf-8")).decode("ascii")

    login_response = requests.post(
        f"{BASE_URL}/api/login",
        data={"username": apt_code, "password": encoded_password},
        headers={
            "User-Agent": "Dart/2.19 (dart:io)",
            "Content-Type": "application/x-www-form-urlencoded; charset=utf-8",
        },
        timeout=15,
    )
    login_response.raise_for_status()
    login = login_response.json()

    if not login.get("result"):
        raise Exception("Apartment label not found.")

    session_id = login.get("session_id")
    if not session_id:
        raise Exception("Gateway communication error.")

    meters_res = requests.get(
        f"{BASE_URL}/api/meters",
        headers={"X-SESSION-ID": session_id, "X-METER-ID": "0", "X-TZ-ID": "2"},
        timeout=15,
    )
    meters_res.raise_for_status()
    meter_list = meters_res.json().get("meters", [])

    if not meter_list:
        raise Exception("No meter found on this account.")

    meter = meter_list[0]
    meter_id = meter.get("meter_id") or meter.get("m_id")
    if not meter_id:
        raise Exception("No meter ID found on this account.")

    status_res = requests.get(
        f"{BASE_URL}/api/status",
        headers={
            "X-SESSION-ID": session_id,
            "X-METER-ID": str(meter_id),
            "X-TZ-ID": "0",
        },
        timeout=15,
    )
    status_res.raise_for_status()
    status = status_res.json()

    raw_account = (
        status.get("con_name")
        or meter.get("con_name")
        or status.get("con_account")
        or meter.get("con_account")
        or status.get("flatnumber")
        or meter.get("flatnumber")
        or apt_code
    )

    return {
        "m_id": meter_id,
        "meter_id": meter_id,
        "con_account": raw_account,
        "con_account_display": clean_account_display(raw_account),
        "serialnumber": status.get("serialnumber") or meter.get("serialnumber") or "Unavailable",
        "tr_balance_last": status.get("tr_balance_last", 0.0),
        "tr_credits": status.get("tr_credits", 0),
        "tr_ts": status.get("tr_ts", "N/A"),
        "active_tariff": status.get("active_tariff"),
    }


