@app.route("/set_language/<lang>")
def set_language(lang):
    if lang not in ("en", "ar"):
        lang = "en"
    session.permanent = True
    session["language"] = lang
    next_url = request.args.get("next", "/")
    # Only allow local paths; avoid redirecting to an external URL.
    if not next_url.startswith("/") or next_url.startswith("//"):
        next_url = "/"
    return redirect(next_url)


@app.route("/")
def index():
    if not session.get("logged_in"):
        return render_template_string(HTML_TEMPLATE, quick_meter=False)

    username = session.get("username", "")
    user = DEMO_USERS.get(username)
    if not user:
        language = current_language()
        session.clear()
        session["language"] = language
        session.permanent = True
        return render_template_string(HTML_TEMPLATE, quick_meter=False, error="Demo session expired. Please login again.")

    active_tab = request.args.get("active_tab", "meter")
    meter_id = user["meter_id"]
    meters = [dict(DEMO_METERS[meter_id])]
    primary_meter = meters[0]
    payments = DEMO_PAYMENTS.get(meter_id, [])

    now = datetime.datetime.now()
    try:
        selected_month = int(request.args.get("month", now.month))
        selected_year = int(request.args.get("year", now.year))
    except ValueError:
        selected_month, selected_year = now.month, now.year

    profile_list = _demo_profile(selected_year, selected_month, meter_id)

    return render_template_string(
        HTML_TEMPLATE,
        quick_meter=False,
        active_tab=active_tab,
        meters=meters,
        primary_meter=primary_meter,
        payments=payments,
        profile_list=profile_list,
        selected_month=selected_month,
        selected_year=selected_year,
        searched_meter=session.get("searched_meter"),
        search_error=session.get("search_error"),
        is_master=bool(user.get("is_master")),
    )


@app.route("/login", methods=["POST"])
def login():
    username = request.form.get("username", "").strip()
    raw_password = request.form.get("password", "").strip()
    user = DEMO_USERS.get(username)

    if user and raw_password == user["password"]:
        session.permanent = True
        session["logged_in"] = True
        session["session_id"] = "DEMO-SESSION"
        session["username"] = username
        return index()

    return render_template_string(
        HTML_TEMPLATE,
        quick_meter=False,
        error="Invalid demo username or password",
    )


@app.route("/quick_check", methods=["POST"])
def quick_check():
    meter_id = request.form.get("meter_id", "").strip()
    try:
        result = _demo_find_by_meter_id(meter_id)
        session["quick_meter_result"] = result
        session.permanent = True
        return redirect("/quick_result")
    except Exception:
        session.pop("quick_meter_result", None)
        return render_template_string(
            HTML_TEMPLATE,
            quick_meter=False,
            error="Meter ID not found in demo data",
        )


@app.route("/quick_result")
def quick_result():
    result = session.get("quick_meter_result")
    if not result:
        return redirect("/")
    return render_template_string(HTML_TEMPLATE, quick_meter=True, quick_data=result)


@app.route("/close_quick_result")
def close_quick_result():
    session.pop("quick_meter_result", None)
    return redirect("/")


@app.route("/settings_quick_check", methods=["POST"])
def settings_quick_check():
    if not session.get("logged_in"):
        return redirect("/")

    username = session.get("username", "")
    user = DEMO_USERS.get(username)
    if not user or not user.get("is_master"):
        return redirect("/?active_tab=settings")

    query = request.form.get("query", "").strip()
    try:
        if not query:
            raise Exception("Please enter an Apartment Label or Meter ID.")
        searched_meter = _demo_find_by_meter_id(query) if query.isdigit() else _demo_find_by_apartment(query)
        session["searched_meter"] = searched_meter
        session.pop("search_error", None)
    except Exception:
        session.pop("searched_meter", None)
        session["search_error"] = "Account or Meter ID not found in demo data."

    session.permanent = True
    return redirect("/?active_tab=settings")


@app.route("/close_modal")
def close_modal():
    session.pop("searched_meter", None)
    session.pop("search_error", None)
    return redirect("/?active_tab=settings")


@app.route("/logout")
def logout():
    language = current_language()
    session.clear()
    session["language"] = language
    session.permanent = True
    return render_template_string(HTML_TEMPLATE, quick_meter=False)


if __name__ == "__main__":
    import os
    port = int(os.environ.get("PORT", 5000))
    app.run(host="0.0.0.0", port=port, debug=True)
